    # Create a dictionary to map each pattern to its corresponding color tuple
    pattern_to_color = {}

    # Iterate over the colors and patterns simultaneously
    for color, pattern in zip(colors, patterns):
        # If the pattern is already in the dictionary, check if the color matches
        if pattern in pattern_to_color:
            if pattern_to_color[pattern] != color:
                return False
        else:
            # Otherwise, add the pattern-color pair to the dictionary
            pattern_to_color[pattern] = color

    # If all patterns match their corresponding colors, return True
