def sumofFactors(n):
    result = 1
    for i in range(2, int(n**0.5) + 1):
        count = 0
        current_sum = 1
        current_term = 1
        while n % i == 0:
            count += 1
            n //= i
            if count % 2 == 1:
                current_sum *= (i + 1)
                current_term *= i
            else:
                current_sum -= current_term
                current_term = i ** (count // 2)
        result *= current_sum
    if n >= 2:
        result *= (n + 1)
    return result - 1

