def is_simple_power(x, n):
    # Check if x is 1, which is a simple power of any number n
    if x == 1:
        return True
    # Check if n is 1, which is not a valid base for a simple power
    elif n == 1:
        return False
    else:
        # Calculate the logarithm of x with base n
        log_result = math.log(x, n)
        # Check if the logarithm result is an integer (simple power)
        return log_result.is_integer()

def is_simple_power(x, n):
    # Check if n is 1, which is a special case
    if n == 1:
        return x == 1

    # Calculate the logarithm base n of x
    log_result = math.log(x, n)

    # Check if the result is an integer
    return log_result.is_integer()

