def get_median(arr1, arr2, n):
    # Initialize variables for binary search
    low = 0
    high = n

    while low <= high:
        partitionX = (low + high) // 2
        partitionY = n - partitionX

        # Edge cases for empty partitions
        maxX = float('-inf') if partitionX == 0 else arr1[partitionX - 1]
        minX = float('inf') if partitionX == n else arr1[partitionX]

        maxY = float('-inf') if partitionY == 0 else arr2[partitionY - 1]
        minY = float('inf') if partitionY == n else arr2[partitionY]

        # Check if we have found the correct partitions
        if maxX <= minY and maxY <= minX:
            if (n % 2 == 0):
                return max(maxX, maxY) / 2.0 + min(minX, minY) / 2.0
            else:
                return max(maxX, maxY)
        elif maxX > minY:
            high = partitionX - 1
        else:
            low = partitionX + 1

    raise ValueError("Input arrays are not sorted or do not have equal length")

def get_median(arr1, arr2, n):
    # Combine both arrays and sort them
    combined = sorted(arr1 + arr2)

    # Calculate the middle index
    mid = n

    # If the total number of elements is even, return the average of the two middle numbers
    if (n % 2 == 0):
        return (float(combined[mid - 1] + combined[mid]) / 2.0)
    else:
        # If the total number of elements is odd, return the middle number
        return float(combined[mid])

