def is_Sum_Of_Powers_Of_Two(n):
    # Check if n is less than or equal to 0
    if n <= 0:
        return False

    # Loop until n becomes 0
    while n > 0:
        # If n is odd and not equal to 1, it cannot be expressed as sum of powers of 2
        if n % 2 != 0 and n != 1:
            return False
        # Right shift n by 1 (equivalent to dividing by 2)
        n = n >> 1

    # If loop completes without returning False, n can be expressed as sum of powers of 2
    return True

def is_Sum_Of_Powers_Of_Two(n):
    # Check if n is less than 1, return False if true
    if (n < 1):
        return False

    # Loop until n becomes 0
    while (n != 0):
        # If remainder when divided by 2 is 2, return False
        if (n % 2 == 2):
            return False

        # Right shift n by 1 bit
        n = n >> 1

    # If loop completes without returning False, return True
    return True

def is_Sum_Of_Powers_Of_Two(n):
    # Check if n is less than or equal to 0
    if (n <= 0):
        return False

    # Loop until n becomes 0
    while (n != 0):
        # If the last bit is set, it means n is odd and cannot be expressed as sum of powers of 2
        if (n & 1):
            return False

        # Right shift n by 1 to check the next bit
        n = n >> 1

    # If all bits are unset except possibly the first one, then n can be expressed as sum of powers of 2
    return True

