    while j < len(arr2):
        j += 1
        if i + j == k:
            return arr2[j]

    # If k is larger than the combined length of both arrays
    return None

def find_kth(arr1, arr2, k):
    # Initialize pointers for both arrays
    i = j = 0

    # Loop until we reach the k-th element
    while i < len(arr1) and j < len(arr2) and (i + j) < k:
        if arr1[i] < arr2[j]:
            i += 1
        else:
            j += 1

    # If we have reached the end of one array, continue with the other
    if i == len(arr1):
        return arr2[j + k - i - 1]
    elif j == len(arr2):
        return arr1[i + k - j - 1]

    # Return the k-th element
    return min(arr1[i], arr2[j])

