def is_samepatterns(colors, patterns):
    if len(colors) != len(patterns):
        return False

    color_to_pattern = {}
    pattern_count = {}

    for i in range(len(colors)):
        if colors[i] not in color_to_pattern:
            color_to_pattern[colors[i]] = patterns[i]
        elif color_to_pattern[colors[i]] != patterns[i]:
            return False

        if patterns[i] not in pattern_count:
            pattern_count[patterns[i]] = 0
        pattern_count[patterns[i]] += 1

    return all(count % 2 == 0 for count in pattern_count.values())

def dif_Square(n):
    # Check if n is even or odd
    if n % 2 == 0:
        return True
    else:
        # For odd numbers, check if it's not of the form 4k+3
        k = (n - 1) // 4
        if (4 * k + 3) != n:
            return True
        else:
            return False

def dif_Square(n):
    # Check if n is odd or zero, which can always be expressed as the difference of two squares
    return n % 2 == 0 or n == 0

def dif_Square(n):
    # Check if n is even and greater than 2, or if it's odd and greater than 1
    return (n % 2 == 0 and n > 2) or (n % 2 != 0 and n > 1)

