class Solution:
    def search(self, arr):
        # Initialize left and right pointers
        left, right = 0, len(arr) - 1

        # Perform binary search
        while left < right:
            mid = (left + right) // 2

            # Check if the middle element is at an even index
            if mid % 2 == 1:
                mid -= 1

            # If the pair is not equal, the single element is on the left side
            if arr[mid] != arr[mid + 1]:
                right = mid
            else:
                # Otherwise, it's on the right side
                left = mid + 2

        # The single element is at the left pointer
        return arr[left]

