def convert_list_dictionary(keys, values, scores):
    result = []
    for key, value, score in zip(keys, values, scores):
        result.append({key: {value: score}})
    return result

def maximize_elements(test_tup1, test_tup2):
    # Initialize an empty list to store the maximized elements
    res = []

    # Iterate over each pair of elements from both tuples
    for ele1, ele2 in zip(test_tup1, test_tup2):
        # Append the maximum element between the current pair to the result list
        res.append(max(ele1, ele2))

    # Convert the result list back to a tuple and return it
    return tuple(res)

