def max_Abs_Diff(arr):
    # Check if the array has less than 2 elements
    if len(arr) < 2:
        return None

    # Initialize minimum and maximum elements as the first element of the array
    min_element = arr[0]
    max_element = arr[0]

    # Iterate through the array starting from the second element
    for num in arr[1:]:
        # Update the minimum element if the current number is smaller
        if num < min_element:
            min_element = num
        # Update the maximum element if the current number is larger
        elif num > max_element:
            max_element = num

    # Calculate the absolute difference between the maximum and minimum elements
    abs_diff = max_element - min_element

    # Return the result as a tuple containing the minimum and maximum elements along with their absolute difference
    return (min_element, max_element, abs_diff)

